struct Widget {
    int data = 0;
    ~Widget() { /* Resource cleanup */ }
};

// Initialization (Preferred C++14+)
std::unique_ptr<Widget> p1 = std::make_unique<Widget>();

// Access
p1->data = 42;

// Cannot copy (Enforces exclusivity)
// std::unique_ptr<Widget> p_err = p1; // ERROR

// Transfer ownership (Move)
std::unique_ptr<Widget> p2 = std::move(p1);

// p1 is now null
if (p1 == nullptr) { /* Check */ }

// Get raw pointer (Use with caution)
Widget* raw = p2.get();

// RAII: Widget is destroyed when p2 goes out of scope.
